style.css:
@-moz-document domain("youtube.com") {
body {
    background-color: #000080; 
    color: #ff0000; 
    font-family: 'Comic Sans MS', cursive, sans-serif; 
    margin: 0;
    padding: 0;
  }

  header, .yt-header, #masthead {
    background-color: #003366; 
    color: #ffcc00; 
  }

  h1, h2, h3, h4, h5, h6, p {
    color: #ff0000;
  }

  button, .ytp-button {
    background-color: #ff0000;
    color: white;
    border: none;
    padding: 15px 30px;
    font-size: 1rem;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s ease;
  }

  button:hover, .ytp-button:hover {
    background-color: #cc0000; 
  }

  footer {
    position: absolute;
    bottom: 0;
    width: 100%;
    text-align: center;
    background-color: #003366;
    color: #ffcc00;
    padding: 10px;
    font-size: 0.9rem;
  }
}
